/**
 * The replay seasons (coaching-bias 25): three six-week fictional seasons
 * that are not marathon blocks, under tests/fixtures/seasons/, regenerated by
 * scripts/regenerate-replay-seasons.ts. Checks the committed packets say what
 * the season scripts say, the exports regenerate byte for byte, and the replay
 * dry run over all eighteen packets passes the three goal checks. Never calls
 * the live model.
 */
import { execFileSync, spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdtempSync, readdirSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { assertPacketHasNoPiiOrGps } from "../src/packet/index.js";
import type { ModelPacket } from "../src/packet/types.js";

const api = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SEASONS = path.join(api, "tests/fixtures/seasons");
const PACKETS = path.join(SEASONS, "season-packets");
const GENERATOR = path.resolve(api, "../demo/generate-season-export.mjs");

type Season = { id: string; athlete: { name: string }; goal: unknown; aboutYou: string; weeks: unknown[] };

const seasonFiles = readdirSync(SEASONS)
  .filter((f) => /^\d+-.+\.json$/.test(f))
  .sort();
const season = (stem: string) => JSON.parse(readFileSync(path.join(SEASONS, `${stem}.json`), "utf8")) as Season;
const packet = (stem: string, week: number) =>
  JSON.parse(readFileSync(path.join(PACKETS, `${stem}-w${week}.json`), "utf8")) as ModelPacket;
const sha256 = (file: string) => createHash("sha256").update(readFileSync(file)).digest("hex");

/** One section of the weekly report, from its heading to the next. */
function section(markdown: string, heading: string): string {
  const m = new RegExp(`^## ${heading}\\s*$([\\s\\S]*?)(?=^## |(?![\\s\\S]))`, "m").exec(markdown);
  return m?.[1] ?? "";
}

describe("replay seasons", () => {
  it("has a stay-fit, a 10k and a return season, six weekly packets each", () => {
    expect(seasonFiles).toEqual(["1-stay-fit.json", "2-10k.json", "3-return.json"]);
    expect(readdirSync(PACKETS).sort()).toEqual(
      seasonFiles.flatMap((f) => [1, 2, 3, 4, 5, 6].map((w) => `${f.replace(/\.json$/, "")}-w${w}.json`)),
    );
  });

  it.each(seasonFiles.map((f) => f.replace(/\.json$/, "")))(
    "every %s packet carries the goal, a short About you and a coaching block, and nothing identifying",
    (stem) => {
      const s = season(stem);
      expect(s.weeks).toHaveLength(6);
      for (let w = 1; w <= 6; w++) {
        const p = packet(stem, w);
        expect(p.goal).toEqual(s.goal);
        expect(p.coaching?.phase).toBeTruthy();
        expect(p.dossier?.body).toBe(s.aboutYou);
        expect(p.dossier!.body.length).toBeLessThan(700);
        expect(p.recapMarkdown).toContain("## Run-by-run");
        expect(p.planWeek).toBeTruthy();
        const text = JSON.stringify(p);
        for (const part of s.athlete.name.split(" ")) expect(text).not.toContain(part);
        assertPacketHasNoPiiOrGps(p, { forbiddenSubstrings: ["LineString", "rawGpxData", "rawFitData"] });
      }
    },
  );

  it("the 10k season's week 4 report shows the parkrun 5K best on the new-bests line", () => {
    const notable = section(packet("2-10k", 4).recapMarkdown!, "Notable");
    expect(notable).toMatch(/^- New best: 5K 21:\d\d \(was 21:55\)$/m);
    for (const w of [1, 2, 3]) expect(packet("2-10k", w).recapMarkdown).not.toContain("New best");
  });

  it("the return season's week 3 report has the one pain score", () => {
    const md = packet("3-return", 3).recapMarkdown!;
    expect(md).toContain("Pain: 3/10 (Left shin ached");
    expect(section(md, "Subjective recap")).toContain("Pain: highest 3/10 (Wed)");
    for (const w of [1, 2, 4, 5, 6]) {
      expect(packet("3-return", w).recapMarkdown).not.toMatch(/Pain: highest [1-9]/);
    }
  });

  it("the exports regenerate byte for byte from the season scripts", () => {
    const out = mkdtempSync(path.join(tmpdir(), "season-export-"));
    for (const f of seasonFiles) {
      const zip = path.join(out, f.replace(/\.json$/, ".zip"));
      execFileSync("node", [GENERATOR, "--season", path.join(SEASONS, f), "--out", zip], { stdio: "ignore" });
      expect(sha256(zip)).toBe(sha256(path.join(SEASONS, f.replace(/\.json$/, ".zip"))));
    }
  }, 30_000);

  it("the replay dry run over all three seasons passes the three goal checks", () => {
    const out = mkdtempSync(path.join(tmpdir(), "replay-seasons-"));
    const env = { ...process.env };
    delete env.ANTHROPIC_API_KEY;
    const run = spawnSync(
      path.join(api, "node_modules/.bin/tsx"),
      ["scripts/replay-weekly-reads.ts", "--packets", PACKETS, "--dry-run", "--out", out],
      { cwd: api, env, encoding: "utf8" },
    );
    expect(run.stderr).toBe("");
    expect(run.status).toBe(0);
    const report = readFileSync(path.join(out, "report.md"), "utf8");
    expect(report).toContain("from 18 replayed weekly calls");
    expect(report).toMatch(/## Goal checks\n\nAll passed/);
    expect(report).toContain("## 18 (3-return-w6.json)");
  }, 60_000);
});
